/**
 * Audit — owner manual 06. Flow: StartAudit → durable interpretation/validation
 * Invariant: The logical audit retains its original deadlines and grant across retries.
 */
export interface Audit {
  /** Logical audit identity. */
  readonly auditId: Id;
  /** Sealed source. */
  readonly revisionId: Id;
  /** Exact target version; absent for CLEAN, whose audit binds the canonical CLEAN target hash. */
  readonly targetContractId?: Id;
  /** Durable visible phase. */
  readonly state: "QUEUED" | "PROFILING" | "INTERPRETING" | "VALIDATING" | "DRAFT_READY" | "NEEDS_DECISION" | "UNSUPPORTED" | "FAILED" | "CANCELLED" | "EXPIRED";
  /** Original logical start. */
  readonly startedAt: UtcInstant;
  /** No new semantic dispatch afterward. */
  readonly interpretationDeadline: UtcInstant;
  /** No successful finalization afterward. */
  readonly absoluteDeadline: UtcInstant;
  /** Funded budget reservation. */
  readonly grantId: Id;
  /** Complete expected candidate set after planning. */
  readonly candidateManifestHash?: Sha256Hex;
  /** Cancellation generation. */
  readonly cancelVersion: Count;
  /** Aggregate concurrency version. */
  readonly version: Version;
}

/**
 * CostGrant — owner manual 06. Flow: Funding authority → provider admission
 * Invariant: A monthly funding statement is not a grant of currently available money.
 */
export interface CostGrant {
  /** Unique spend allocation. */
  readonly grantId: Id;
  /** Accounting currency. */
  readonly currency: "USD";
  /** Total authorized maximum liability. */
  readonly ceilingCents: MoneyMinorUnits;
  /** Possible in-flight liability. */
  readonly reservedCents: MoneyMinorUnits;
  /** Known consumption under the actual tariff. */
  readonly reconciledSpendCents: MoneyMinorUnits;
  /** Derived remaining amount; never browser-provided authority. */
  readonly availableCents: MoneyMinorUnits;
  /** Exact dated rates and conservative overhead. */
  readonly priceProfileHash: Sha256Hex;
  /** Actual session/account authorization evidence. */
  readonly authorizationRef: Id;
  /** No new spend after expiry. */
  readonly expiresAt: UtcInstant;
  /** Grant state. */
  readonly state: "PREPARED" | "AUTHORIZED" | "EXHAUSTED" | "EXPIRED" | "CLOSED";
  /** Atomic concurrent reservation guard. */
  readonly version: Version;
}

/**
 * Candidate — owner manual 06. Flow: Full profile/target planner → semantic compiler
 * Invariant: Coverage and permissible choices are fixed before provider response evaluation.
 */
export interface Candidate {
  /** Stable nonidentifying identity. */
  readonly candidateId: Id;
  /** One supported family. */
  readonly family: "OBJECT_MAPPING" | "FIELD_MAPPING" | "SEMANTIC_TYPE" | "TRANSFORMATION_SELECTION" | "VALUE_MAP" | "IDENTITY_STRATEGY" | "DUPLICATE_SIGNAL_STRATEGY" | "ASSOCIATION_MAPPING" | "UNMAPPED_HANDLING" | "TARGET_REQUIREMENT" | "CONSISTENCY_REVIEW" | "SEMANTIC_REPAIR";
  /** Exact source object/field set. */
  readonly sourceScopeHash: Sha256Hex;
  /** Exact allowed destination set. */
  readonly targetScopeHash: Sha256Hex;
  /** Closed allowed alternatives including explicit abstention where appropriate. */
  readonly alternativeIds: string[];
  /** Candidate-specific allowed operation subset. */
  readonly primitiveIds: string[];
  /** Facts needed for authoritative resolution. */
  readonly requiredFactHashes: Sha256Hex[];
  /** Cross-task dependencies preserved by partitioning. */
  readonly dependencyCandidateIds: string[];
  /** Minimized outbound classification/substitution policy. */
  readonly privacyProfileHash: Sha256Hex;
}

/**
 * MemoryDecision — owner manual 06. Flow: Previously accepted scoped decision → future candidate assistance
 * Invariant: Memory is evidence with scope and expiry, never automatic authority.
 */
export interface MemoryDecision {
  /** Immutable memory record. */
  readonly memoryId: Id;
  /** Tenant owner. */
  readonly agencyId: Id;
  /** End-client boundary. */
  readonly clientId: Id;
  /** Compatible structural source context. */
  readonly sourceShapeHash: Sha256Hex;
  /** Compatible target scope. */
  readonly targetContractHash: Sha256Hex;
  /** Original accepted decision. */
  readonly decisionEvidenceHash: Sha256Hex;
  /** Applicable operation/privacy policy. */
  readonly policyVersion: string;
  /** Creation time. */
  readonly createdAt: UtcInstant;
  /** Retention/compatibility endpoint. */
  readonly expiresAt: UtcInstant;
  /** Stops selection and provider egress. */
  readonly revokedAt?: UtcInstant;
  /** Actual content classification. */
  readonly privacy: "L0" | "L1" | "L2" | "L3" | "L4";
}

/**
 * PrimitiveDefinition — owner manual 04. Flow: Reviewed core catalogue → candidate/compiler
 * Invariant: A primitive is executable only within its typed input/output/effect contract.
 */
export interface PrimitiveDefinition {
  /** Stable operation name. */
  readonly primitiveId: string;
  /** Behavioral version. */
  readonly version: string;
  /** Closed trusted schema. */
  readonly parameterSchemaId: string;
  /** Permitted semantic types. */
  readonly inputTypes: string[];
  /** Declared result type. */
  readonly outputType: string;
  /** Qualified CLEAN/HUBSPOT/SALESFORCE contexts. */
  readonly allowedModes: string[];
  /** Risk/authority classification. */
  readonly effect: "PRESERVING" | "NORMALIZING" | "DERIVING" | "IDENTITY_AFFECTING" | "DESTRUCTIVE";
  /** Necessary but not sufficient approval condition. */
  readonly requiresAgencyAuthority: boolean;
  /** Bounded algorithm and scratch requirements. */
  readonly resourceClass: string;
  /** Current independent semantic/capacity evidence. */
  readonly acceptanceEvidenceHashes: Sha256Hex[];
}

/**
 * PaymentAttempt — owner manual 15. Flow: Payment intent → provider/reconciliation
 * Invariant: Network failure alone cannot establish no external effect.
 */
export interface PaymentAttempt {
  /** Physical payment/refund attempt. */
  readonly attemptId: Id;
  /** Logical commercial order. */
  readonly orderId: Id;
  /** Explicit provider effect. */
  readonly operation: "CREATE_ORDER" | "CAPTURE" | "REFUND" | "WITHDRAW";
  /** Durable uncertainty semantics. */
  readonly state: "PREPARED" | "DISPATCHING" | "PROVIDER_PENDING" | "CONFIRMED" | "FAILED_NO_EFFECT" | "UNCERTAIN" | "CANCELLED_BEFORE_DISPATCH";
  /** Exact normalized intended provider request. */
  readonly requestHash: Sha256Hex;
  /** Observed provider idempotency/request identity. */
  readonly providerRequestId?: string;
  /** Attempt start. */
  readonly startedAt: UtcInstant;
  /** Most recent authenticated observation. */
  readonly lastObservedAt: UtcInstant;
  /** Final or uncertain provider evidence. */
  readonly evidenceHash?: Sha256Hex;
}

/**
 * PriceEligibilitySnapshot — owner manual 16. Flow: Qualifying agency history → immutable quote
 * Invariant: A price snapshot cannot change after capture because later history changes.
 */
export interface PriceEligibilitySnapshot {
  /** Eligibility identity. */
  readonly snapshotId: Id;
  /** Commercial buyer. */
  readonly agencyId: Id;
  /** Owning quote. */
  readonly quoteId: Id;
  /** Server issuance/cutoff. */
  readonly asOf: UtcInstant;
  /** Exact 365-day boundary. */
  readonly lookbackStartsAt: UtcInstant;
  /** Complete prior distinct paid/non-fully-refunded project set. */
  readonly qualifyingProjectIds: string[];
  /** Must equal that unique set size. */
  readonly qualifyingCount: Count;
  /** Tier-derived discount. */
  readonly repeatDiscountBps: BasisPoints;
  /** Atomic promotion reservation if eligible. */
  readonly foundingSlotRef?: Id;
  /** Maximum eligible rate without stacking. */
  readonly appliedDiscountBps: BasisPoints;
  /** Price/promotion rule version. */
  readonly policyVersion: string;
}

/**
 * RetentionRecord — owner manual 09. Flow: Admission/payment/stage lifecycle → deletion scheduler
 * Invariant: The effective deadline is a minimum of named anchors; retries do not extend it.
 */
export interface RetentionRecord {
  /** Lifecycle policy identity. */
  readonly retentionId: Id;
  /** Affected data boundary. */
  readonly scope: TenantScope;
  /** Owning retention class. */
  readonly class: "UNPAID" | "PENDING_PAYMENT_HOLD" | "PAID_ORDINARY" | "PAID_STAGED" | "IMPORT_RECEIPT" | "TARGET_METADATA" | "ORDINARY_LOG" | "SECURITY_LOG" | "LEGAL_FINANCIAL";
  /** Actual seal/capture/ready/stage/terminal facts. */
  readonly anchorEvidenceHash: Sha256Hex;
  /** Policy interval from the applicable ready event. */
  readonly softDeadline?: UtcInstant;
  /** Absolute maximum from the owning immutable event; only the one extension of an UNPAID record may move it, to at most the policy's UNPAID ceiling from sealing. */
  readonly hardDeadline: UtcInstant;
  /** Minimum active deadline after all relevant caps. */
  readonly effectiveDeadline: UtcInstant;
  /** Retention rule at collection/contract. */
  readonly policyVersion: string;
  /** Observed classes that outlive active access with reasons. */
  readonly providerResiduals: string[];
  /** Actual managed lifecycle. */
  readonly state: "ACTIVE" | "EXPIRED" | "DELETING" | "DELETED_WITH_RESIDUALS" | "DELETED";
}

/**
 * DomainEvent — owner manual 07. Flow: Atomic command transaction → outbox/inbox consumers
 * Invariant: Payload is allowlisted references and safe counts, never raw CRM rows.
 */
export interface DomainEvent {
  /** Unique durable event. */
  readonly eventId: Id;
  /** Owning aggregate. */
  readonly aggregateId: Id;
  /** Committed ordering within aggregate. */
  readonly aggregateVersion: Version;
  /** Tenant scope where applicable. */
  readonly agencyId?: Id;
  /** Registered versioned event type. */
  readonly eventType: string;
  /** Command or prior event cause. */
  readonly causationId: Id;
  /** Safe operation trace. */
  readonly correlationId: Id;
  /** Server event time. */
  readonly createdAt: UtcInstant;
  /** Closed event-specific payload/reference artifact. */
  readonly payloadArtifactHash: Sha256Hex;
  /** Consumer compatibility version. */
  readonly schemaVersion: string;
}

/**
 * OutboxRecord — owner manual 07. Flow: Atomic domain write → at-least-once dispatcher
 * Invariant: Outbox delivery is not the business effect itself.
 */
export interface OutboxRecord {
  /** Dispatch record. */
  readonly outboxId: Id;
  /** Atomic domain event. */
  readonly eventId: Id;
  /** Registered destination. */
  readonly consumer: string;
  /** Dispatcher lifecycle. */
  readonly state: "PENDING" | "CLAIMED" | "DELIVERED" | "RETRYABLE" | "DEAD_LETTER";
  /** Physical dispatch count. */
  readonly attempts: Count;
  /** Bounded retry schedule. */
  readonly nextAttemptAt: UtcInstant;
  /** Current dispatcher owner. */
  readonly lease?: Lease;
  /** Transport acceptance observation. */
  readonly deliveredAt?: UtcInstant;
  /** Safe classified failure. */
  readonly lastErrorCode?: string;
}

/**
 * InboxRecord — owner manual 07. Flow: Authenticated ingress → idempotent consumer
 * Invariant: Environment and provider identity participate in deduplication.
 */
export interface InboxRecord {
  /** Durable receipt. */
  readonly inboxId: Id;
  /** Origin. */
  readonly provider: string;
  /** Prevents cross-environment collision. */
  readonly environment: "LOCAL" | "SANDBOX" | "LIVE";
  /** Observed unique external identity. */
  readonly externalEventId: string;
  /** Authenticated exact event body digest. */
  readonly bodyHash: Sha256Hex;
  /** Actual consumer outcome. */
  readonly state: "RECEIVED" | "PROCESSING" | "APPLIED" | "IGNORED" | "RETRYABLE" | "REJECTED";
  /** Server receipt time. */
  readonly receivedAt: UtcInstant;
  /** Committed business application. */
  readonly appliedAt?: UtcInstant;
  /** Resulting domain event, if any. */
  readonly resultEventId?: Id;
}

/**
 * QualificationRun — owner manual 21. Flow: Actual campaign runner → independent aggregator
 * Invariant: Run identity must represent a separate actual invocation on the same candidate.
 */
export interface QualificationRun {
  /** Unique physical campaign identity. */
  readonly runId: Id;
  /** Code/model/prompt/policy/adapter subject. */
  readonly candidateHash: Sha256Hex;
  /** Exact substantive input manifest. */
  readonly corpusHash: Sha256Hex;
  /** Presealed independent expected answers. */
  readonly truthHash: Sha256Hex;
  /** Accepted scorer bytes. */
  readonly evaluatorHash: Sha256Hex;
  /** Resources/runtime/transport profile. */
  readonly runnerProfileHash: Sha256Hex;
  /** Actual process/provider provenance. */
  readonly invocationEvidenceHash: Sha256Hex;
  /** Complete raw/minimized result inventory. */
  readonly resultArtifactHash: Sha256Hex;
  /** Actual start. */
  readonly startedAt: UtcInstant;
  /** Actual completion. */
  readonly completedAt: UtcInstant;
  /** Complete unique case count. */
  readonly caseCount: Count;
  /** Actual observed critical violations. */
  readonly criticalFailures: Count;
  /** Correct useful supported cases. */
  readonly supportedSuccesses: Count;
  /** Applicable supported cases. */
  readonly supportedDenominator: Count;
  /** No incomplete run counted as qualification. */
  readonly status: "COMPLETED" | "INCOMPLETE" | "HARNESS_ERROR" | "CANCELLED";
}

/**
 * ModelProfile — owner manual 06. Flow: Current provider/privacy review → dispatch adapter
 * Invariant: A model name alone is not an eligible transport or production winner.
 */
export interface ModelProfile {
  /** Versioned endpoint profile. */
  readonly profileId: Id;
  /** Actual provider/platform. */
  readonly provider: string;
  /** Exact served/requested model identity. */
  readonly modelId: string;
  /** Actual route. */
  readonly region: string;
  /** Request shape and audience binding without credentials. */
  readonly endpointProfileHash: Sha256Hex;
  /** Effective retention/cache/log read-back and terms. */
  readonly privacyEvidenceHash: Sha256Hex;
  /** Current conservative rates/overheads. */
  readonly priceProfileHash: Sha256Hex;
  /** Actual supported request contract. */
  readonly requestSchemaHash: Sha256Hex;
  /** Measured status. */
  readonly state: "PROPOSED" | "ELIGIBLE_FOR_PILOT" | "QUALIFIED" | "INELIGIBLE" | "RETIRED";
  /** Independent final campaigns where required. */
  readonly qualificationEvidenceHashes: Sha256Hex[];
}

/**
 * ReportSnapshot — owner manual 13. Flow: Verified domain facts → safe rendering
 * Invariant: Presentation cannot invent facts or expose raw data beyond the chosen report class.
 */
export interface ReportSnapshot {
  /** Immutable report model. */
  readonly reportId: Id;
  /** Delivered package. */
  readonly packageId: Id;
  /** Independent named measures. */
  readonly counts: RowCounts;
  /** Complete relevant findings. */
  readonly findingIds: string[];
  /** Disclosed high-impact decisions. */
  readonly materialDecisionIds: string[];
  /** Tenant branding snapshot. */
  readonly brandingVersion: string;
  /** Relevant service scope/retention. */
  readonly termsVersion: string;
  /** Canonical rendering input. */
  readonly modelHash: Sha256Hex;
  /** Pinned HTML/PDF generator. */
  readonly rendererVersion: string;
  /** Authorized audience. */
  readonly privacyClass: "AGENCY_SUMMARY" | "SECURE_DETAIL" | "INTERNAL_EVIDENCE";
}

/**
 * ReleaseCandidate — owner manual 21. Flow: Frozen build → reviewer/promotion
 * Invariant: A changed dependency or image produces a different candidate even with identical source text.
 */
export interface ReleaseCandidate {
  /** Release identity. */
  readonly candidateId: Id;
  /** Full code commit. */
  readonly sourceCommit: GitObjectName;
  /** Exact tree. */
  readonly sourceTree: GitObjectName;
  /** Pinned resolved dependencies. */
  readonly dependencyLockHash: Sha256Hex;
  /** Actual installed MC/IC bytes. */
  readonly corePackageHashes: Sha256Hex[];
  /** Exact OCI content digests without display aliases. */
  readonly imageDigests: Sha256Hex[];
  /** Wire/domain contract versions. */
  readonly contractBundleHash: Sha256Hex;
  /** Material behavior/configuration. */
  readonly policyHash: Sha256Hex;
  /** Complete immutable qualification graph. */
  readonly evidenceManifestHash: Sha256Hex;
  /** Reviewer-owned acceptance transition. */
  readonly state: "PREPARED" | "FROZEN" | "UNDER_REVIEW" | "ACCEPTED" | "REJECTED" | "PROMOTED" | "RETIRED";
}

/**
 * CommissionAdjustment — owner manual 17. Flow: Refund/dispute reconciliation → seller ledger
 * Invariant: An adjustment records a difference without editing historical paid lines.
 */
export interface CommissionAdjustment {
  /** Unique adjustment. */
  readonly adjustmentId: Id;
  /** Original accrual. */
  readonly commissionLineId: Id;
  /** Grounded cause. */
  readonly reason: "REFUND" | "REVERSAL" | "SPLIT_CORRECTION" | "AGREED_ERROR_CORRECTION";
  /** Explicit sign. */
  readonly direction: "INCREASE" | "DECREASE";
  /** Exact difference from prior cumulative entitlement. */
  readonly amountCents: MoneyMinorUnits;
  /** Recomputed current entitlement. */
  readonly newCumulativeEntitlementCents: MoneyMinorUnits;
  /** Reconciled financial or reviewed correction event. */
  readonly sourceEventId: Id;
  /** Posting time. */
  readonly createdAt: UtcInstant;
  /** Lawful applicable adjustment/offset terms. */
  readonly agreementVersion: string;
}

/**
 * OutreachDraft — owner manual 18. Flow: Assigned seller/owner → authorization and sender
 * Invariant: Editing a draft cannot send it or imply recipient permission.
 */
export interface OutreachDraft {
  /** Stable draft identity. */
  readonly draftId: Id;
  /** Authorized business recipient record. */
  readonly prospectId: Id;
  /** Registry-bound human sender. */
  readonly senderIdentityRef: Id;
  /** Reviewed contact purpose. */
  readonly purpose: "REQUESTED_REPLY" | "INDIVIDUAL_PROSPECT_CONTACT" | "FOLLOW_UP";
  /** Exact safe subject/body/recipient/sender binding. */
  readonly contentHash: Sha256Hex;
  /** Private draft content reference; never raw customer CRM. */
  readonly contentRef: Id;
  /** Source and permission/legal-policy basis. */
  readonly provenanceEvidenceHash: Sha256Hex;
  /** Optimistic concurrency boundary. */
  readonly version: Version;
  /** Observed Kavo send/activity state. */
  readonly state: "DRAFT" | "AUTHORIZED" | "SUBMITTING" | "PROVIDER_ACCEPTED" | "SEND_UNCERTAIN" | "BOUNCED" | "REPLIED" | "SUPPRESSED" | "CANCELLED";
  /** Creation time. */
  readonly createdAt: UtcInstant;
}

/**
 * OutreachAuthorization — owner manual 18. Flow: Explicit owner grant → bounded dispatch
 * Invariant: Permission is specific to recipients, content, sender, purpose, time and count.
 */
export interface OutreachAuthorization {
  /** Immutable grant identity. */
  readonly authorizationId: Id;
  /** Authenticated authorized owner. */
  readonly grantingActorId: Id;
  /** Permitted sender. */
  readonly senderIdentityRef: Id;
  /** Sealed recipient/content combinations. */
  readonly allowedContentHashes: Sha256Hex[];
  /** Inclusive beginning. */
  readonly validFrom: UtcInstant;
  /** Exclusive deadline. */
  readonly expiresAt: UtcInstant;
  /** Bounded positive maximum, also no greater than sealed unique drafts. */
  readonly maximumSends: Count;
  /** Actual explicit authorization. */
  readonly permissionEvidenceHash: Sha256Hex;
  /** Applicable provider, suppression and contact policy. */
  readonly policyVersion: string;
  /** Current server-observed revocation, checked at dispatch. */
  readonly revoked: boolean;
}

/**
 * SalesActivity — owner manual 18. Flow: Sender/reconciler → scoped commercial history
 * Invariant: Observed submission, receipt and customer response are different facts.
 */
export interface SalesActivity {
  /** Unique activity event. */
  readonly activityId: Id;
  /** Scoped business record. */
  readonly prospectId: Id;
  /** Bound draft. */
  readonly draftId: Id;
  /** Authority applied to this event. */
  readonly authorizationId: Id;
  /** Exact evidence class. */
  readonly kind: "PROVIDER_ACCEPTED" | "SEND_UNCERTAIN" | "BOUNCED" | "REPLIED" | "SUPPRESSED" | "HUMAN_SEND_OBSERVED";
  /** Observed event time; unknown time cannot be fabricated. */
  readonly occurredAt: UtcInstant;
  /** Minimal safe supporting record. */
  readonly evidenceHash: Sha256Hex;
  /** Opaque external identity or explicit NONE for a local suppression. */
  readonly providerMessageRef: string;
}

/**
 * ProjectDate — owner manual 09. Flow: Quote, retention records, extension and hold → the project dates read
 * Invariant: One date of one kind with its own rule; a date is never derived by adding another kind's period, and an estimate is never shown as a commitment.
 */
export interface ProjectDate {
  /** Which of the five dates (F-24); PENDING_PAYMENT_HOLD is reserved (the item's reservation) and NOT_APPLICABLE until CP-02.17 is active. */
  readonly kind: "QUOTE_PRICE_VALIDITY" | "FREE_CHECK_RETENTION" | "EXTENSION" | "PENDING_PAYMENT_HOLD" | "PAID_RETENTION";
  /** NOT_APPLICABLE: no anchor yet or not offered; AVAILABLE: may be requested (extension); RUNNING; ENDED; USED: the one extension was granted. */
  readonly state: "NOT_APPLICABLE" | "AVAILABLE" | "RUNNING" | "ENDED" | "USED";
  /** The date itself, when the anchor exists. */
  readonly at?: UtcInstant;
  /** Retention kinds only: the absolute maximum the record allows (14 days from sealing, 17 with the UNPAID extension under CP-01.02). */
  readonly hardLimit?: UtcInstant;
  /** The policy key that sets the date, e.g. pricing.quoteDays or retention.unpaidDaysFromReady. */
  readonly rule: string;
  /** The version the date was computed under: pricing.scheduleVersion or the record's retention label. */
  readonly policyVersion: string;
  /** The fact the date counts from. */
  readonly anchor: "QUOTE_ISSUED" | "REVISION_READY" | "REVISION_SEALED" | "EXTENSION_GRANTED" | "PROOF_ACCEPTED" | "PAYMENT_CAPTURED" | "FIRST_PACKAGE_AVAILABLE" | "NONE";
  /** When the anchor happened. */
  readonly anchoredAt?: UtcInstant;
  /** The quote, retention record, extension or hold the date is read from. */
  readonly sourceId?: Id;
  /** What may be done about this date now; RECORD_TRANSFER_PROOF only after CP-02.17. */
  readonly actionAvailable: "REQUEST_EXTENSION" | "REQUEST_NEW_QUOTE" | "RECORD_TRANSFER_PROOF" | "REQUEST_DELETION" | "NONE";
  /** Who may do it (the command's registry role; Order 15 enforces it). */
  readonly actionRole: "AGENCY_OWNER_OR_ADMIN" | "AGENCY_BILLING" | "NONE";
}

/**
 * ProjectDates — owner manual 09. Flow: Project, quote and retention journals → agency screens (Quote, Payment, Overview, Projects, Data and deletion, Billing)
 * Invariant: Exactly one entry per kind, in the order of the kind enum; the governing retention kind names which date deletes the data, it never adds two dates.
 */
export interface ProjectDates {
  /** The project. */
  readonly projectId: Id;
  /** The five dates, one per kind. */
  readonly dates: ProjectDate[];
  /** The retention date that currently governs deletion (the later of extension and hold, never their sum). */
  readonly governingRetentionKind: "FREE_CHECK_RETENTION" | "EXTENSION" | "PENDING_PAYMENT_HOLD" | "PAID_RETENTION" | "NONE";
  /** Database time of the read. */
  readonly computedAt: UtcInstant;
}

/**
 * ProjectSummary — owner manual 11. Flow: Project, client and lifecycle journals → the shell header, menu and board
 * Invariant: The stage is derived from durable facts at read time; it is a label for navigation, never authority for a command.
 */
export interface ProjectSummary {
  /** Project. */
  readonly projectId: Id;
  /** Owning agency. */
  readonly agencyId: Id;
  /** Owning client workspace. */
  readonly clientId: Id;
  /** The client's display name. */
  readonly clientDisplayName: string;
  /** The project's purpose as its name (CMD011 purpose). */
  readonly name: string;
  /** Service. */
  readonly mode: "CLEAN" | "HUBSPOT" | "SALESFORCE";
  /** Current stage (for CLEAN, IMPORT never appears). */
  readonly stage: "FILES" | "HEALTH_CHECK" | "PLAN" | "APPROVAL" | "QUOTE" | "PAYMENT" | "PREPARATION" | "DELIVERY" | "IMPORT" | "CLOSED" | "DELETION";
  /** Project state. */
  readonly state: "OPEN" | "CLOSED" | "DELETION_REQUESTED" | "DELETED";
  /** Who the next step waits for. */
  readonly waitingOn: "AGENCY" | "KAURO" | "NOBODY";
  /** A blocker or a date within the alert window exists. */
  readonly needsAction: boolean;
  /** Latest committed activity entry. */
  readonly lastActivityAt?: UtcInstant;
  /** Project version. */
  readonly version: Version;
}

/**
 * ProjectStageCount — owner manual 11. Flow: Project summaries → board
 * Invariant: Counts only the caller's agency.
 */
export interface ProjectStageCount {
  /** Stage. */
  readonly stage: "FILES" | "HEALTH_CHECK" | "PLAN" | "APPROVAL" | "QUOTE" | "PAYMENT" | "PREPARATION" | "DELIVERY" | "IMPORT" | "CLOSED" | "DELETION";
  /** Projects in it. */
  readonly count: Count;
}

/**
 * BoardSummary — owner manual 11. Flow: Project summaries → the agency board
 * Invariant: Counts are of the caller's agency at one database instant.
 */
export interface BoardSummary {
  /** Agency. */
  readonly agencyId: Id;
  /** Projects per stage. */
  readonly stages: ProjectStageCount[];
  /** Projects needing action. */
  readonly needsActionCount: Count;
  /** Active clients. */
  readonly clientCount: Count;
  /** Database time of the read. */
  readonly computedAt: UtcInstant;
}

/**
 * ClientSummary — owner manual 11. Flow: End clients and their projects → client list
 * Invariant: A client label is presentation; legal and data boundaries stay those of EndClient.
 */
export interface ClientSummary {
  /** Client. */
  readonly clientId: Id;
  /** Display name. */
  readonly displayName: string;
  /** Client state. */
  readonly state: "ACTIVE" | "ARCHIVED";
  /** Open projects. */
  readonly openProjectCount: Count;
  /** Open projects needing action. */
  readonly needsActionCount: Count;
  /** Latest activity among its projects. */
  readonly lastActivityAt?: UtcInstant;
}

/**
 * FindingExampleRef — owner manual 06. Flow: Audit finding → the existing table preview read
 * Invariant: A reference, never a value: the cell is read through PreviewTable under its own authorization and the plan's privacy class.
 */
export interface FindingExampleRef {
  /** Sealed revision. */
  readonly revisionId: Id;
  /** Table of the revision. */
  readonly tableId: Id;
  /** Row position in the table. */
  readonly rowOrdinal: Count;
  /** Source column header. */
  readonly columnName: string;
}

/**
 * AuditFindingSummary — owner manual 06. Flow: Audit result → results page (P-07)
 * Invariant: Counts and references only; no cell value, and no more examples than the plan's privacy class allows.
 */
export interface AuditFindingSummary {
  /** Audit. */
  readonly auditId: Id;
  /** The core's finding token; the web maps it to its copy (consequence and fix). */
  readonly findingCode: string;
  /** Effect on the plan. */
  readonly severity: "BLOCKING" | "WARNING" | "INFO";
  /** Rows examined for this finding. */
  readonly population: Count;
  /** Rows affected. */
  readonly affectedCount: Count;
  /** The plan can carry a fix. */
  readonly fixAvailable: boolean;
  /** At most five references. */
  readonly examples: FindingExampleRef[];
}

/**
 * PriceEstimate — owner manual 15. Flow: Audit measurement and the price policy → estimate after the free check (F-05)
 * Invariant: An estimate, never a quote or a reservation: no discount, tax, founding slot or terms; the quote (CMD027) decides the price.
 */
export interface PriceEstimate {
  /** Project. */
  readonly projectId: Id;
  /** Audit that measured the units. */
  readonly auditId: Id;
  /** Service. */
  readonly mode: "CLEAN" | "HUBSPOT" | "SALESFORCE";
  /** Measured units (billableUnitsOf). */
  readonly billableUnits: Count;
  /** Base price of the band in the current schedule (baseCentsOf). */
  readonly policyBaseServiceCents: MoneyMinorUnits;
  /** Currency. */
  readonly currency: "USD";
  /** pricing.scheduleVersion used. */
  readonly scheduleVersion: string;
  /** Always ESTIMATE. */
  readonly nature: "ESTIMATE";
  /** Database time. */
  readonly computedAt: UtcInstant;
}

/**
 * ActivityEntry — owner manual 11. Flow: Domain events of the project → activity (F-06, G-10)
 * Invariant: Built from committed events of the caller's agency only; payload references, never labels or rows.
 */
export interface ActivityEntry {
  /** The domain event id. */
  readonly entryId: Id;
  /** Project. */
  readonly projectId: Id;
  /** Registered event type, e.g. dataset_revision.sealed.v1. */
  readonly eventType: string;
  /** Commit time. */
  readonly occurredAt: UtcInstant;
  /** Who acted; a Kauro person is never named. */
  readonly actorKind: "AGENCY_MEMBER" | "KAURO" | "SYSTEM" | "PAYMENT_PROVIDER";
  /** The member, when an agency member acted. */
  readonly actorMembershipId?: Id;
  /** Aggregate kind. */
  readonly subjectKind: string;
  /** Aggregate id. */
  readonly subjectId: Id;
}

/**
 * BillingProfileSummary — owner manual 15. Flow: Agency legal and fiscal profile, captures → billing settings (G-05)
 * Invariant: Reads what CMD002 and CMD027 require; no tax rate is inferred.
 */
export interface BillingProfileSummary {
  /** Agency. */
  readonly agencyId: Id;
  /** Profile completeness for a quote. */
  readonly state: "MISSING" | "INCOMPLETE" | "COMPLETE";
  /** Agency.legalProfileRef. */
  readonly legalProfileRef?: Id;
  /** FiscalProfile.taxTreatment in force. */
  readonly taxTreatment?: "REVIEW_REQUIRED" | "DOMESTIC_TAXABLE" | "EXEMPT_EXPORT" | "OTHER_REVIEWED";
  /** FiscalProfile.territory. */
  readonly territory?: string;
  /** Projects with a captured payment in pricing.repeatLookbackDays (the repeat-discount count). */
  readonly paidProjectCount: Count;
  /** Agency version. */
  readonly version: Version;
}

/**
 * BillingDocumentItem — owner manual 15. Flow: Quotes and payment orders of the agency's projects → billing overview (F-10)
 * Invariant: A captured payment is the only 'paid'; an issued tax document is never shown as money received.
 */
export interface BillingDocumentItem {
  /** Document kind. */
  readonly kind: "QUOTE" | "PAYMENT_ORDER";
  /** Quote or order id. */
  readonly documentId: Id;
  /** Project. */
  readonly projectId: Id;
  /** The document's state token. */
  readonly state: string;
  /** Total. */
  readonly totalCents: MoneyMinorUnits;
  /** Currency. */
  readonly currency: "USD";
  /** Which date keyDate is. */
  readonly keyDateKind: "QUOTE_PRICE_VALIDITY" | "TRANSFER_DUE" | "CAPTURED" | "ENDED";
  /** The date that matters now. */
  readonly keyDate?: UtcInstant;
  /** Issued tax document number, if any. */
  readonly fiscalDocumentNumber?: string;
  /** Refunds on the order. */
  readonly refundCount: Count;
}

/**
 * PackageArtifactItem — owner manual 13. Flow: Package manifest artifacts → delivery page
 * Invariant: Customer-facing artifacts only: the vocabulary has no EVIDENCE role and no INTERNAL_EVIDENCE privacy, so internal evidence cannot be listed.
 */
export interface PackageArtifactItem {
  /** Artifact. */
  readonly artifactId: Id;
  /** Path inside the package. */
  readonly relativePath: string;
  /** Role. */
  readonly role: "IMPORT_DATA" | "REJECTIONS" | "LINEAGE" | "MANIFEST" | "REPORT" | "INSTRUCTIONS";
  /** Bytes digest. */
  readonly sha256: Sha256Hex;
  /** Size. */
  readonly bytes: Count;
  /** Media type. */
  readonly mediaType: string;
  /** Records. */
  readonly recordCount?: Count;
  /** Privacy class. */
  readonly privacy: "CUSTOMER_DATA" | "SAFE_SUMMARY";
  /** CRM object, for import data. */
  readonly objectApiName?: string;
}

/**
 * PackageSummary — owner manual 13. Flow: Package version and manifest → delivery page (G-06)
 * Invariant: Lists customer-facing artifacts only (PackageArtifactItem has no internal evidence).
 */
export interface PackageSummary {
  /** Package. */
  readonly packageId: Id;
  /** Project. */
  readonly projectId: Id;
  /** Package version state. */
  readonly state: "STAGED" | "VERIFIED_PRIVATE" | "AVAILABLE" | "RETIRED" | "REVOKED" | "DELETED";
  /** Manifest version. */
  readonly manifestVersion: string;
  /** Customer-facing artifacts. */
  readonly artifacts: PackageArtifactItem[];
  /** Rows in import data. */
  readonly acceptedRowCount: Count;
  /** Rows in the rejections file. */
  readonly rejectedRowCount: Count;
  /** Download availability end (the PAID_RETENTION date). */
  readonly availableUntil?: UtcInstant;
  /** Independent verification time. */
  readonly verifiedAt?: UtcInstant;
}

/**
 * DeletionRecordItem — owner manual 09. Flow: Deletion requests of the agency → Data and deletion (G-10)
 * Invariant: A receipt of what was deleted and what stays outside the managed scope; never the tombstone itself.
 */
export interface DeletionRecordItem {
  /** Deletion request. */
  readonly deletionId: Id;
  /** Project. */
  readonly projectId: Id;
  /** Trigger. */
  readonly reason: "RETENTION" | "AGENCY_REQUEST" | "ACCOUNT_CLOSURE" | "INCIDENT" | "END_OF_SERVICE";
  /** State. */
  readonly state: "REQUESTED" | "AUTHORITY_REVOKED" | "DELETING" | "VERIFYING" | "COMPLETED" | "RESIDUAL_HOLD" | "FAILED_RETRYABLE";
  /** Request time. */
  readonly requestedAt: UtcInstant;
  /** Verification time. */
  readonly verifiedAt?: UtcInstant;
  /** Residual classes held, by token. */
  readonly residualClasses: string[];
}

/**
 * RefundListItem — owner manual 15. Flow: Refunds of the agency's orders → refunds list (G-14)
 * Invariant: A refund is a reconciled effect; REQUESTED or APPROVED is never shown as money returned.
 */
export interface RefundListItem {
  /** Refund. */
  readonly refundId: Id;
  /** Agency of the order. */
  readonly agencyId: Id;
  /** Project. */
  readonly projectId: Id;
  /** Payment order. */
  readonly orderId: Id;
  /** State. */
  readonly state: "REQUESTED" | "APPROVED" | "SUBMITTING" | "UNCERTAIN" | "COMPLETED" | "FAILED" | "REJECTED";
  /** Service amount. */
  readonly serviceCents: MoneyMinorUnits;
  /** Tax amount. */
  readonly taxCents: MoneyMinorUnits;
  /** Origin. */
  readonly origin: "CUSTOMER_REQUEST" | "EXCESS_CAPTURE" | "KAURO_REMEDY";
  /** Request time. */
  readonly requestedAt: UtcInstant;
  /** Completion time. */
  readonly completedAt?: UtcInstant;
}

/**
 * RetentionExtension — owner manual 09. Flow: RequestRetentionExtension (CMD060) → scheduler, dates read and restore journal
 * Invariant: One per project across every retention class; it never revives expired data, and only an UNPAID record's extension may move its hard deadline, to at most the policy's UNPAID ceiling from sealing.
 */
export interface RetentionExtension {
  /** Extension. */
  readonly extensionId: Id;
  /** Project. */
  readonly projectId: Id;
  /** Governing retention record. */
  readonly retentionId: Id;
  /** Class of the extended record. */
  readonly retentionClass: "UNPAID" | "PAID_ORDINARY" | "PAID_STAGED";
  /** Requested, at most retention.softExtensionMaximumSeconds. */
  readonly requestedSeconds: Count;
  /** Granted after the cap. */
  readonly grantedSeconds: Count;
  /** Soft deadline before. */
  readonly previousSoftDeadline: UtcInstant;
  /** Soft deadline after. */
  readonly softDeadline: UtcInstant;
  /** Hard deadline before. */
  readonly previousHardDeadline: UtcInstant;
  /** Hard deadline after (moves for UNPAID only). */
  readonly hardDeadline: UtcInstant;
  /** The most the extension could reach: the hard deadline for paid classes, sealing plus retention.extendHardCapExceptions.UNPAID.ceilingDaysFromSeal for UNPAID. */
  readonly ceilingDeadline: UtcInstant;
  /** Which ceiling applied. */
  readonly ceilingRule: "ORIGINAL_HARD_CAP" | "UNPAID_EXCEPTIONAL_CEILING";
  /** retention.policyVersion in force (R2-RETENTION-2 after CP-01.02). */
  readonly policyVersion: string;
  /** Database time. */
  readonly grantedAt: UtcInstant;
}

/**
 * ConsentRecord — owner manual 08. Flow: The person's own explicit act (registration, contact form, preferences) → proof store and restore journal
 * Invariant: One record per act, kind and channel; never pre-ticked or bundled; a session, a login or a step-up is never a consent; withdrawal is a new state of the same record, never an edit of its proof.
 */
export interface ConsentRecord {
  /** Record. */
  readonly consentId: Id;
  /** The person. */
  readonly userId: Id;
  /** What was authorized; MARKETING_COMMUNICATIONS is separate and optional (POL 8.3). */
  readonly kind: "DATA_PROCESSING_AUTHORIZATION" | "PRIVACY_NOTICE_ACKNOWLEDGEMENT" | "MARKETING_COMMUNICATIONS";
  /** Marketing channel; NOT_APPLICABLE for the other kinds. */
  readonly channel: "EMAIL" | "CALL" | "SMS" | "MESSAGING" | "NOT_APPLICABLE";
  /** Version of the text presented. */
  readonly documentVersion: string;
  /** SHA-256 of the exact text presented. */
  readonly documentHash: Sha256Hex;
  /** Where the act happened. */
  readonly source: "REGISTRATION" | "CONTACT_FORM" | "PREFERENCES";
  /** State. */
  readonly state: "GIVEN" | "WITHDRAWN";
  /** Database time of the act. */
  readonly givenAt: UtcInstant;
  /** Database time of the withdrawal. */
  readonly withdrawnAt?: UtcInstant;
  /** Hash of the evidence bundle (presented text hash, unticked-by-default control state, user, time). */
  readonly evidenceHash: Sha256Hex;
  /** Record version. */
  readonly version: Version;
}

/**
 * ConsentView — owner manual 08. Flow: ConsentRecord → the person's own settings
 * Invariant: What the person gave and when; the server's evidence hash stays out.
 */
export interface ConsentView {
  /** Record. */
  readonly consentId: Id;
  /** Kind. */
  readonly kind: "DATA_PROCESSING_AUTHORIZATION" | "PRIVACY_NOTICE_ACKNOWLEDGEMENT" | "MARKETING_COMMUNICATIONS";
  /** Channel. */
  readonly channel: "EMAIL" | "CALL" | "SMS" | "MESSAGING" | "NOT_APPLICABLE";
  /** Version presented. */
  readonly documentVersion: string;
  /** State. */
  readonly state: "GIVEN" | "WITHDRAWN";
  /** When. */
  readonly givenAt: UtcInstant;
  /** When withdrawn. */
  readonly withdrawnAt?: UtcInstant;
  /** MARKETING_COMMUNICATIONS only. */
  readonly withdrawable: boolean;
  /** Record version. */
  readonly version: Version;
}

/**
 * NotificationPreference — owner manual 11. Flow: The person's choices → NOTIFICATIONS consumer
 * Invariant: An ESSENTIAL topic is always enabled; marketing is not a topic (it is a ConsentRecord).
 */
export interface NotificationPreference {
  /** Topic. */
  readonly topic: "ACCOUNT_SECURITY" | "BILLING_AND_PAYMENTS" | "DATA_RETENTION_AND_DELETION" | "LEGAL_AND_TERMS" | "CLAIMS_AND_PAYOUTS" | "PROJECT_PROGRESS" | "ALERT_DIGEST";
  /** Channel (e-mail only in V1). */
  readonly channel: "EMAIL";
  /** ESSENTIAL topics cannot be disabled. */
  readonly class: "ESSENTIAL" | "OPTIONAL";
  /** Whether the person receives it. */
  readonly enabled: boolean;
}

/**
 * NotificationPreferenceChoice — owner manual 11. Flow: SetNotificationPreferences request member
 * Invariant: Names an OPTIONAL topic; an ESSENTIAL one is refused.
 */
export interface NotificationPreferenceChoice {
  /** Topic. */
  readonly topic: "ACCOUNT_SECURITY" | "BILLING_AND_PAYMENTS" | "DATA_RETENTION_AND_DELETION" | "LEGAL_AND_TERMS" | "CLAIMS_AND_PAYOUTS" | "PROJECT_PROGRESS" | "ALERT_DIGEST";
  /** Channel. */
  readonly channel: "EMAIL";
  /** Choice. */
  readonly enabled: boolean;
}

/**
 * NotificationPreferences — owner manual 11. Flow: The person's settings
 * Invariant: Every topic appears once; essential ones enabled.
 */
export interface NotificationPreferences {
  /** The person. */
  readonly userId: Id;
  /** One per topic and channel. */
  readonly preferences: NotificationPreference[];
  /** Settings version. */
  readonly version: Version;
}

/**
 * ClaimReview — owner manual 17. Flow: RequestClaimReview → the owner's decision (CP-02.14) → claim history
 * Invariant: At most one open review per claim decision; a review never changes a claim by itself.
 */
export interface ClaimReview {
  /** Review. */
  readonly reviewId: Id;
  /** Claim. */
  readonly claimId: Id;
  /** The seller who asked. */
  readonly sellerId: Id;
  /** UPHELD and CHANGED are set by DecideClaimReview (CP-02.14). */
  readonly state: "REQUESTED" | "UPHELD" | "CHANGED";
  /** Database time. */
  readonly requestedAt: UtcInstant;
  /** Decision time. */
  readonly decidedAt?: UtcInstant;
  /** Version. */
  readonly version: Version;
}

/**
 * SellerClaimView — owner manual 17. Flow: AttributionClaim, its review and the policy message → the seller's claims and home
 * Invariant: The seller reads the neutral message only (OPS-2); never the internal reason, evidence, note or another seller's claim.
 */
export interface SellerClaimView {
  /** Claim. */
  readonly claimId: Id;
  /** The seller's own prospect. */
  readonly prospectId: Id;
  /** Prospect organization as the seller registered it. */
  readonly organizationLabel: string;
  /** Claim state. */
  readonly state: "SUBMITTED" | "ACCEPTED" | "DISPUTED" | "REJECTED" | "EXPIRED" | "CONVERTED";
  /** Acceptance. */
  readonly acceptedAt?: UtcInstant;
  /** End of the claim (the 14- and 3-day alerts count to it). */
  readonly expiresAt: UtcInstant;
  /** The neutral message of a refusal or of 'Not available to claim'. */
  readonly sellerMessage?: string;
  /** The latest review's state. */
  readonly reviewState: "NONE" | "REQUESTED" | "UPHELD" | "CHANGED";
  /** A review may be requested now. */
  readonly reviewAvailable: boolean;
  /** Claim version. */
  readonly version: Version;
}

/**
 * ClaimDecisionEntry — owner manual 17. Flow: kauro.commercial_transitions of a claim → the owner's claim history
 * Invariant: Append-only, in commit order; the owner sees reason, evidence and note.
 */
export interface ClaimDecisionEntry {
  /** Claim. */
  readonly claimId: Id;
  /** Order of the entry. */
  readonly sequence: Count;
  /** What happened. */
  readonly kind: "SUBMITTED" | "ACCEPTED" | "REFUSED" | "NOT_AVAILABLE" | "REVIEW_REQUESTED" | "REVIEW_UPHELD" | "REVIEW_CHANGED" | "EXPIRED" | "CONVERTED";
  /** Commit time. */
  readonly at: UtcInstant;
  /** Who. */
  readonly actorKind: "SELLER" | "KAURO_OWNER" | "SYSTEM";
  /** Refusal or decision code (closed list after CP-01.04). */
  readonly reasonCode?: string;
  /** Evidence of the decision. */
  readonly evidenceRef?: Id;
  /** The owner's note or the seller's review note. */
  readonly note?: string;
  /** What the seller read. */
  readonly sellerMessage?: string;
}

/**
 * SellerClaimDecisionEntry — owner manual 17. Flow: kauro.commercial_transitions of the seller's own claim → the seller's history
 * Invariant: The seller's projection of ClaimDecisionEntry: no reason, evidence or note.
 */
export interface SellerClaimDecisionEntry {
  /** Claim. */
  readonly claimId: Id;
  /** Order. */
  readonly sequence: Count;
  /** What happened. */
  readonly kind: "SUBMITTED" | "ACCEPTED" | "REFUSED" | "NOT_AVAILABLE" | "REVIEW_REQUESTED" | "REVIEW_UPHELD" | "REVIEW_CHANGED" | "EXPIRED" | "CONVERTED";
  /** Commit time. */
  readonly at: UtcInstant;
  /** The neutral message. */
  readonly sellerMessage?: string;
}

/**
 * SellerListItem — owner manual 17. Flow: Sellers, agreements and claims → the owner's Sellers page (P-21)
 * Invariant: Owner only; rates and retainer are the agreement in force; money figures are CP-02.09's.
 */
export interface SellerListItem {
  /** Seller. */
  readonly sellerId: Id;
  /** Name. */
  readonly displayName: string;
  /** Seller state. */
  readonly state: "CANDIDATE" | "ACTIVE" | "SUSPENDED" | "TERMINATED";
  /** Agreement in force. */
  readonly agreementId?: Id;
  /** First-project rate. */
  readonly firstBps?: BasisPoints;
  /** Repeat rate. */
  readonly repeatBps?: BasisPoints;
  /** Signed retainer (0 by default, CP-01.05). */
  readonly retainerCentsPerMonth?: MoneyMinorUnits;
  /** Customers attributed or served. */
  readonly customerCount: Count;
  /** Live claims. */
  readonly liveClaimCount: Count;
}

/**
 * CustomerListItem — owner manual 17. Flow: Agencies, buyer type, attribution, assignment and captures → Customers (P-23)
 * Invariant: Net revenue is collections net of refunds without tax, never invoices; one capture counts once.
 */
export interface CustomerListItem {
  /** Customer agency. */
  readonly agencyId: Id;
  /** Agency display name. */
  readonly displayName: string;
  /** A3 3.7 buyer type. */
  readonly buyerType: "AGENCY" | "IN_HOUSE" | "NOT_RECORDED";
  /** Whether an accepted attribution exists. */
  readonly channel: "SELLER_ATTRIBUTED" | "NOT_ATTRIBUTED";
  /** Accepted attribution's seller. */
  readonly acquiringSellerId?: Id;
  /** Current service assignment (CMD048). */
  readonly servingSellerId?: Id;
  /** Projects with a capture. */
  readonly paidProjectCount: Count;
  /** Collections net of completed refunds, tax excluded, all time. */
  readonly netRevenueCents: MoneyMinorUnits;
  /** First durable capture. */
  readonly firstPaymentAt?: UtcInstant;
  /** Latest final completion. */
  readonly lastCompletionAt?: UtcInstant;
}

/**
 * StatementPeriodItem — owner manual 17. Flow: Commission statements of a period across sellers → Payouts (P-22)
 * Invariant: One row per issued statement version; amounts are the statement's.
 */
export interface StatementPeriodItem {
  /** Statement. */
  readonly statementId: Id;
  /** Payee. */
  readonly sellerId: Id;
  /** Inclusive. */
  readonly periodStart: UtcInstant;
  /** Exclusive. */
  readonly periodEnd: UtcInstant;
  /** State. */
  readonly state: "DRAFT" | "ISSUED" | "DISPUTED" | "APPROVED" | "PAID" | "CORRECTED";
  /** Payable. */
  readonly payableCents: MoneyMinorUnits;
  /** Held. */
  readonly heldCents: MoneyMinorUnits;
}

/**
 * OwnerClaimItem — owner manual 17. Flow: Claims across sellers → Claims (P-24)
 * Invariant: Owner only.
 */
export interface OwnerClaimItem {
  /** Claim. */
  readonly claimId: Id;
  /** Prospect. */
  readonly prospectId: Id;
  /** Seller. */
  readonly sellerId: Id;
  /** Prospect organization. */
  readonly organizationLabel: string;
  /** State. */
  readonly state: "SUBMITTED" | "ACCEPTED" | "DISPUTED" | "REJECTED" | "EXPIRED" | "CONVERTED";
  /** Acceptance. */
  readonly acceptedAt?: UtcInstant;
  /** End. */
  readonly expiresAt: UtcInstant;
  /** A review is REQUESTED. */
  readonly openReview: boolean;
  /** History length. */
  readonly decisionCount: Count;
}

/**
 * SellerRecordView — owner manual 17. Flow: One seller's agreement, customers, statements and claims → Seller (UI37)
 * Invariant: Owner only.
 */
export interface SellerRecordView {
  /** The seller. */
  readonly seller: SellerListItem;
  /** Agreement in force. */
  readonly agreement?: SellerAgreement;
  /** Customers attributed or served. */
  readonly customers: CustomerListItem[];
  /** Statements, newest first. */
  readonly statements: StatementPeriodItem[];
  /** Claims, newest first. */
  readonly claims: OwnerClaimItem[];
}

/**
 * SellerWonCustomer — owner manual 17. Flow: The seller's converted claims → seller home (G-11)
 * Invariant: Only the seller's own converted claims; dates, never amounts of the customer.
 */
export interface SellerWonCustomer {
  /** Converted claim. */
  readonly claimId: Id;
  /** Organization. */
  readonly organizationLabel: string;
  /** First capture. */
  readonly firstPaymentAt?: UtcInstant;
  /** Final completion of the first project. */
  readonly finalCompletionAt?: UtcInstant;
  /** Eligibility date (30 days after final completion). */
  readonly commissionEligibleOn?: UtcInstant;
}

/**
 * SellerSchedule — owner manual 17. Flow: Claims, lines and the statement calendar → seller home (G-11)
 * Invariant: The seller's own records; dates from commission.statementBusinessDay and payBusinessDay.
 */
export interface SellerSchedule {
  /** Live claims with end dates. */
  readonly claims: SellerClaimView[];
  /** Won customers. */
  readonly wonCustomers: SellerWonCustomer[];
  /** Next line eligibility. */
  readonly nextEligibleOn?: UtcInstant;
  /** Next statement date. */
  readonly nextStatementOn?: UtcInstant;
  /** Next payment date. */
  readonly nextPaymentOn?: UtcInstant;
  /** Database time. */
  readonly computedAt: UtcInstant;
}

/**
 * SellerMoneySummary — owner manual 17. Flow: Captures, refunds and commission lines → Sellers (P-21), Seller (UI37), seller home
 * Invariant: Collections, never invoices: a collection counts in the month its capture was confirmed and a refund in the month it happened, never rewriting an earlier period; tax excluded; one capture counted once and split shares applied once; earned, held, payable and paid kept apart; pending = held + payable as of computedAt.
 */
export interface SellerMoneySummary {
  /** Seller; absent on the total row. */
  readonly sellerId?: Id;
  /** Inclusive. */
  readonly periodStart: UtcInstant;
  /** Exclusive. */
  readonly periodEnd: UtcInstant;
  /** What attributed customers paid for the service, collections confirmed in the period net of refunds that happened in the period, tax excluded; never Kauro's revenue. */
  readonly netAttributableRevenueCents: MoneyMinorUnits;
  /** Commission earned on that revenue in the period, after offsets. */
  readonly commissionGeneratedCents: MoneyMinorUnits;
  /** Earned not yet paid, as of computedAt: held plus payable. */
  readonly commissionPendingCents: MoneyMinorUnits;
  /** Held, as of computedAt. */
  readonly commissionHeldCents: MoneyMinorUnits;
  /** Payable, as of computedAt. */
  readonly commissionPayableCents: MoneyMinorUnits;
  /** Paid in the period. */
  readonly commissionPaidCents: MoneyMinorUnits;
  /** Offsets applied in the period. */
  readonly refundOffsetCents: MoneyMinorUnits;
  /** commission.collectionPeriod in force (MONTH_OF_CONFIRMED_CAPTURE). */
  readonly collectionPeriodRule: string;
  /** commission.refundPeriod in force (MONTH_IN_WHICH_THE_REFUND_HAPPENED). */
  readonly refundPeriodRule: string;
  /** Currency. */
  readonly currency: "USD";
  /** Database time. */
  readonly computedAt: UtcInstant;
}

/**
 * StatementBalance — owner manual 17. Flow: Statement lines, adjustments and retainer accruals → statement balance
 * Invariant: payable = earned − offsets + retainer − held, in exact minor units; each figure is a sum of the statement's own items.
 */
export interface StatementBalance {
  /** Commission lines payable before offsets. */
  readonly earnedCents: MoneyMinorUnits;
  /** Offsets applied under the agreement in force. */
  readonly offsetCents: MoneyMinorUnits;
  /** Retainer accrued for the period (0 unless a signed agreement sets one). */
  readonly retainerCents: MoneyMinorUnits;
  /** Held. */
  readonly heldCents: MoneyMinorUnits;
  /** Payable. */
  readonly payableCents: MoneyMinorUnits;
}

/**
 * StatementBalanceItem — owner manual 17. Flow: Adjustments, offsets and retainer accruals → statement
 * Invariant: An offset names its refund, the adjusted line and the clause; a retainer names its month; nothing is applied without the agreement in force.
 */
export interface StatementBalanceItem {
  /** Item kind. */
  readonly kind: "OFFSET" | "REPAYMENT_REVIEW" | "WRITE_OFF" | "DISPUTE" | "RETAINER";
  /** The statement line: the commission line, the adjustment or the retainer accrual. */
  readonly lineId: Id;
  /** Amount. */
  readonly amountCents: MoneyMinorUnits;
  /** Effect on payable. */
  readonly direction: "INCREASE" | "DECREASE";
  /** OFFSET: the refund. */
  readonly refundId?: Id;
  /** OFFSET: the refunded project. */
  readonly projectId?: Id;
  /** OFFSET: the commission line adjusted. */
  readonly adjustedLineId?: Id;
  /** OFFSET: the agreement clause or rule applied. */
  readonly clauseRef?: string;
  /** RETAINER: first instant of the accrued month. */
  readonly accrualMonthStart?: UtcInstant;
}

/**
 * AlertCondition — owner manual 17. Flow: Alert evaluation → second line of an alert
 * Invariant: A condition of the same subject; it never produces a second alert.
 */
export interface AlertCondition {
  /** Kind. */
  readonly kind: "BLOCKED" | "DEADLINE_PASSED" | "DEADLINE_SOON" | "INACTIVE";
  /** What triggers it, e.g. FILE_DELETION, QUOTE_EXPIRY, PAYMENT_DUE, CLAIM_END, PILOT_REVIEW. */
  readonly conditionCode: string;
  /** The date concerned. */
  readonly dueAt?: UtcInstant;
}

/**
 * Alert — owner manual 17. Flow: Projects, claims, pilot reviews and the alerts policy → Today (UI33), seller home
 * Invariant: Each subject appears once, under its most urgent kind (alerts.precedence); its other conditions are its second line.
 */
export interface Alert {
  /** Deterministic key of subject and kind (de-duplicates sends). */
  readonly alertKey: Sha256Hex;
  /** Subject. */
  readonly subjectKind: "PROJECT" | "CLAIM" | "PILOT_REVIEW";
  /** Subject id. */
  readonly subjectId: Id;
  /** Project alerts: the agency. */
  readonly agencyId?: Id;
  /** Most urgent kind. */
  readonly kind: "BLOCKED" | "DEADLINE_PASSED" | "DEADLINE_SOON" | "INACTIVE";
  /** Trigger of the main kind. */
  readonly conditionCode: string;
  /** The date concerned. */
  readonly dueAt?: UtcInstant;
  /** When the condition began. */
  readonly since: UtcInstant;
  /** INACTIVE: the latest act of alerts.relevantProgress.counts. */
  readonly lastMaterialProgressAt?: UtcInstant;
  /** The second line. */
  readonly otherConditions: AlertCondition[];
  /** Edition of the alerts policy applied. */
  readonly policyVersion: string;
}

/**
 * SellerAlertView — owner manual 17. Flow: Alert evaluation of the seller's own claims → seller home
 * Invariant: Only the seller's own claims; no project, agency or pilot alert.
 */
export interface SellerAlertView {
  /** Deterministic key. */
  readonly alertKey: Sha256Hex;
  /** Always a claim. */
  readonly subjectKind: "CLAIM";
  /** The seller's claim. */
  readonly claimId: Id;
  /** Claim end passed or within the alert days. */
  readonly kind: "DEADLINE_PASSED" | "DEADLINE_SOON";
  /** CLAIM_END. */
  readonly conditionCode: string;
  /** The claim's end. */
  readonly dueAt: UtcInstant;
  /** When the condition began. */
  readonly since: UtcInstant;
  /** Edition of the alerts policy applied. */
  readonly policyVersion: string;
}

/**
 * PolicyLegalStatus — owner manual 17. Flow: policy.legalStatus → owner settings (P-04) and claims (P-24)
 * Invariant: Approving a rule does not validate it legally; the state says so until counsel's validation is recorded.
 */
export interface PolicyLegalStatus {
  /** e.g. commission.claimRules. */
  readonly ruleGroup: string;
  /** Legal state. */
  readonly state: "PENDING_COUNSEL" | "VALIDATED";
  /** Since when. */
  readonly since: UtcInstant;
  /** Policy keys covered. */
  readonly covers: string[];
  /** Counsel's validation reference. */
  readonly validationRef?: string;
}

/**
 * StatementCsvRow — owner manual 17. Flow: CommissionStatement → CSV export
 * Invariant: RFC 4180, UTF-8, one header row; a cell starting with =, +, -, @, tab or carriage return is prefixed with an apostrophe; amounts are minor units; no customer CRM data.
 */
export interface StatementCsvRow {
  /** Statement. */
  readonly statementId: Id;
  /** Row kind. */
  readonly rowKind: "LINE" | "BALANCE_ITEM" | "TOTAL";
  /** Line or item. */
  readonly lineId?: Id;
  /** Customer agency of a line. */
  readonly agencyId?: Id;
  /** Project of a line. */
  readonly projectId?: Id;
  /** Line sequence. */
  readonly sequence?: "FIRST" | "REPEAT" | "ASSISTANCE";
  /** Balance item kind. */
  readonly balanceKind?: "OFFSET" | "REPAYMENT_REVIEW" | "WRITE_OFF" | "DISPUTE" | "RETAINER";
  /** Basis. */
  readonly netServiceBasisCents?: MoneyMinorUnits;
  /** Rate. */
  readonly rateBps?: BasisPoints;
  /** Share. */
  readonly shareBps?: BasisPoints;
  /** Amount. */
  readonly amountCents: MoneyMinorUnits;
  /** Effect on payable. */
  readonly direction: "INCREASE" | "DECREASE";
  /** Offset's refund. */
  readonly refundId?: Id;
  /** Offset's clause. */
  readonly clauseRef?: string;
}

/**
 * OutreachAuthorizationRequest — owner manual 17. Flow: A seller's draft → the owner's outreach review
 * Invariant: A request is neither an authorization nor the recipient's consent; only AuthorizeOutreach (CMD062) grants, bound to content hashes.
 */
export interface OutreachAuthorizationRequest {
  /** Request. */
  readonly requestId: Id;
  /** The draft (CMD061). */
  readonly draftId: Id;
  /** Assigned seller. */
  readonly sellerId: Id;
  /** Draft content asked for. */
  readonly contentHash: Sha256Hex;
  /** GRANTED when an authorization covering contentHash is committed. */
  readonly state: "REQUESTED" | "GRANTED" | "DECLINED" | "EXPIRED";
  /** Database time. */
  readonly requestedAt: UtcInstant;
  /** Decision time. */
  readonly decidedAt?: UtcInstant;
  /** The granting OutreachAuthorization. */
  readonly authorizationId?: Id;
  /** Owner's decline code. */
  readonly declineCode?: string;
  /** Version. */
  readonly version: Version;
}

/**
 * SellerOutreachRequestView — owner manual 17. Flow: OutreachAuthorizationRequest → the assigned seller
 * Invariant: The seller reads the state of their own request; never the owner's decline code or note.
 */
export interface SellerOutreachRequestView {
  /** Request. */
  readonly requestId: Id;
  /** The draft. */
  readonly draftId: Id;
  /** State. */
  readonly state: "REQUESTED" | "GRANTED" | "DECLINED" | "EXPIRED";
  /** Database time. */
  readonly requestedAt: UtcInstant;
  /** Decision time. */
  readonly decidedAt?: UtcInstant;
  /** The granting authorization, once GRANTED. */
  readonly authorizationId?: Id;
  /** Version. */
  readonly version: Version;
}

/**
 * ClaimRefusal — owner manual 17. Flow: RefuseAttribution → claim history and the seller's neutral message
 * Invariant: The code is one of commission.claimRefusalReasons of listVersion; evidence on every refusal; OTHER needs a note; OWNER_RULE names a versioned rule in force when the claimed facts happened, never a later one; the seller message derives from the code, never from the note.
 */
export interface ClaimRefusal {
  /** Refusal. */
  readonly refusalId: Id;
  /** Claim. */
  readonly claimId: Id;
  /** Closed code. */
  readonly reasonCode: string;
  /** commission.claimRefusalListVersion. */
  readonly listVersion: string;
  /** Owner's evidence. */
  readonly evidenceRef: Id;
  /** OWNER_RULE: the rule id and version in force at the decision. */
  readonly ownerRuleRef?: string;
  /** Required for OTHER. */
  readonly note?: string;
  /** Derived from the code. */
  readonly sellerMessage: string;
  /** Database time. */
  readonly refusedAt: UtcInstant;
}

/**
 * IdentityGroupView — owner manual 06. Flow: Plan identities and the core's evidence classification → plan page (UI20)
 * Invariant: PROVEN_IDENTITY only from Migration Core's proving keys without a blocking conflict; same normalized e-mail and full name is a CANDIDATE, never proof; nothing is folded to manufacture a proof; a CANDIDATE is unified only by a person.
 */
export interface IdentityGroupView {
  /** Group. */
  readonly groupId: Id;
  /** Object. */
  readonly objectScope: string;
  /** Class (identityResolution). */
  readonly evidenceClass: "PROVEN_IDENTITY" | "CANDIDATE" | "BLOCKED";
  /** The proving key, for PROVEN_IDENTITY; NONE otherwise. */
  readonly provingKey: "SOURCE_RECORD_ID_WITHIN_ONE_IDENTITY_SPACE" | "AUTHORITATIVE_EXTERNAL_ID_VERIFIED" | "NONE";
  /** Signals of a candidate, e.g. SAME_NORMALIZED_EMAIL, SAME_NORMALIZED_FULL_NAME. */
  readonly candidateSignals: string[];
  /** Blocking conflicts (identityResolution.blockingConflicts). */
  readonly conflictCodes: string[];
  /** Records in the group. */
  readonly memberCount: Count;
  /** Current decision. */
  readonly decision: "UNDECIDED" | "UNIFY" | "KEEP_SEPARATE";
  /** Who decided. */
  readonly decidedBy: "PERSON" | "PROVEN_IDENTITY_RULE" | "NOBODY";
  /** Batch that applied it. */
  readonly batchId?: Id;
}

/**
 * PlanDecisionPreview — owner manual 06. Flow: A batch's exact effects → apply or decide must match
 * Invariant: The apply or the decision binds previewHash; any change in the groups makes it stale.
 */
export interface PlanDecisionPreview {
  /** Plan. */
  readonly planId: Id;
  /** Which groups the preview covers. */
  readonly evidenceClass: "PROVEN_IDENTITY" | "CANDIDATE";
  /** Hash of the exact effects. */
  readonly previewHash: Sha256Hex;
  /** Groups affected. */
  readonly groupCount: Count;
  /** Excluded by conflicts. */
  readonly excludedCount: Count;
  /** Time. */
  readonly computedAt: UtcInstant;
}

/**
 * IdentityDecisionRecord — owner manual 06. Flow: Every identity decision → plan history and approval disclosures
 * Invariant: Records decision, evidence, responsible person, version and effect (identityResolution.decisionRecord); append-only.
 */
export interface IdentityDecisionRecord {
  /** Record. */
  readonly decisionId: Id;
  /** Plan. */
  readonly planId: Id;
  /** Plan version decided on. */
  readonly planVersion: Version;
  /** Group. */
  readonly groupId: Id;
  /** Decision. */
  readonly decision: "UNDECIDED" | "UNIFY" | "KEEP_SEPARATE";
  /** Evidence class at the decision. */
  readonly evidenceClass: "PROVEN_IDENTITY" | "CANDIDATE" | "BLOCKED";
  /** Hash of the evidence the decision saw. */
  readonly evidenceHash: Sha256Hex;
  /** Who. */
  readonly decidedBy: "PERSON" | "PROVEN_IDENTITY_RULE";
  /** The person (PERSON), or the member who applied the proven rule. */
  readonly responsibleMembershipId?: Id;
  /** Effect in the plan (Kauro never writes to a CRM). */
  readonly effect: "MERGE_IN_PLAN" | "KEEP_SEPARATE_IN_PLAN" | "RETURNED_TO_UNDECIDED";
  /** Batch. */
  readonly batchId?: Id;
  /** Time. */
  readonly decidedAt: UtcInstant;
}

/**
 * TransferProof — owner manual 15. Flow: The customer's proof of a sent transfer → owner review → pending-payment hold
 * Invariant: Not payment; proof of a transfer already sent, exact amount and reference; once per quote and per sealed set; never renewed; with an extension the later date applies within the ceiling, never the sum; the effective end is the earlier of five US banking days (FedACH calendar) from the accepted proof and 24 days from sealing, and that is the date the customer sees; never authorizes preparation (F-23).
 */
export interface TransferProof {
  /** Proof. */
  readonly proofId: Id;
  /** Payment order. */
  readonly orderId: Id;
  /** Quote. */
  readonly quoteId: Id;
  /** Amount sent. */
  readonly amountCents: MoneyMinorUnits;
  /** The order's reference as sent. */
  readonly reference: string;
  /** The bank's confirmation document. */
  readonly artifactSha256: Sha256Hex;
  /** Date the bank sent it. */
  readonly sentOn: UtcInstant;
  /** State. */
  readonly state: "SUBMITTED" | "ACCEPTED" | "REFUSED" | "MATCHED" | "ENDED_UNPAID";
  /** Effective end once ACCEPTED: the earlier of five US banking days from acceptance and 24 days from sealing. */
  readonly holdEndsAt?: UtcInstant;
  /** Why refused. */
  readonly refusalCode?: string;
}

/**
 * BlockedImportRow — owner manual 04. Flow: Reconciliation → stage read
 * Invariant: A blocked row is never guessed into a link; it names its reason and the action.
 */
export interface BlockedImportRow {
  /** Source key reference (hash or row id, never a value). */
  readonly rowRef: string;
  /** AMBIGUOUS, REJECTED_BY_CRM, UNMATCHED, KEY_IMPORTED_TWICE. */
  readonly reasonCode: string;
  /** What to do. */
  readonly action: "CORRECT_AND_RESUBMIT" | "CHOOSE_KEPT_ID" | "CONTACT_SUPPORT";
}

/**
 * ImportStageReconciliation — owner manual 04. Flow: Returned result files → stage read (UI27, UI28)
 * Invariant: Only IDs proved by the returned evidence enter a generated stage.
 */
export interface ImportStageReconciliation {
  /** Stage. */
  readonly stageId: Id;
  /** Parent links. */
  readonly parentStageIds: string[];
  /** Stage generated from proved IDs. */
  readonly generated: boolean;
  /** Blocked rows. */
  readonly blockedRows: BlockedImportRow[];
  /** Dependants held back. */
  readonly heldBackCount: Count;
  /** Hash of the returned files. */
  readonly evidenceSha256: Sha256Hex;
}

/**
 * FreeCheckAvailability — owner manual 14. Flow: Funded envelope and capacity → public free-check page
 * Invariant: States only whether new free checks are open; never the budget, a count or an id.
 */
export interface FreeCheckAvailability {
  /** PAUSED at intelligence.freeAuditPauseBps of the funded envelope (CP-01.03) or when capacity is unavailable. */
  readonly state: "OPEN" | "PAUSED";
  /** When. */
  readonly checkedAt: UtcInstant;
}

/**
 * FreeCheckEligibility — owner manual 02. Flow: Eligibility step → onboarding record (A3 3.7)
 * Invariant: Recorded before real files; it decides no price.
 */
export interface FreeCheckEligibility {
  /** Record. */
  readonly eligibilityId: Id;
  /** Person. */
  readonly userId: Id;
  /** A3 3.7. */
  readonly buyerType: "AGENCY" | "IN_HOUSE";
  /** Service asked for. */
  readonly service: "CLEAN" | "HUBSPOT" | "SALESFORCE";
  /** Approximate records. */
  readonly recordsBand: "UP_TO_50K" | "UP_TO_150K" | "UP_TO_500K" | "UP_TO_1M" | "ABOVE_1M";
  /** Within the published bands and service scope. */
  readonly eligible: boolean;
  /** Time. */
  readonly recordedAt: UtcInstant;
}

